function fetchUser(id: string, includeFullProfile: boolean) {
  if (includeFullProfile) {
    return db.users.findWithProfile(id);
  }
  return db.users.findBasic(id);
}

fetchUser('u_123', true);

goodExample.code:
// Good: Explicit intent and decoupled responsibilities
function fetchBasicUser(id: string) {
  return db.users.findBasic(id);
}

function fetchUserWithProfile(id: string) {
  return db.users.findWithProfile(id);
}

fetchUserWithProfile('u_123');

