// Bad: Deep arrow anti-pattern
function processOrder(order: Order) {
  if (order.isValid) {
    if (order.hasInventory) {
      if (order.paymentAuthorized) {
        executeFulfillment(order);
      } else {
        throw new Error('Payment unauthorized');
      }
    } else {
      throw new Error('Out of stock');
    }
  } else {
    throw new Error('Invalid order');
  }
}

goodExample.code:
// Good: Linear execution with guard clauses
function processOrder(order: Order) {
  if (!order.isValid) throw new Error('Invalid order');
  if (!order.hasInventory) throw new Error('Out of stock');
  if (!order.paymentAuthorized) throw new Error('Payment unauthorized');

  executeFulfillment(order);
}
